INSERT INTO grammar.content_catalog_topics(version,slug,catalog_hash,payload) VALUES('core-2026-09-v3','ellipsis-substitution','e49c6c64b6333354230b05b223ded19e0e7519c1828bf3f36aee778f9f3f39c4','{"slug":"ellipsis-substitution","title":"Ellipsis, substitution and avoiding repetition","level":"C1","order":64,"summary":"Leave out recoverable words and use substitutes without losing the intended meaning.","guidance":"Read the form and meaning together. Study the contrasts, then explain a worked example in your own words before starting a fresh practice session.","learningGoals":["Keep the auxiliary, omit repeated content","So and neither for shared experience","One and ones replace count nouns","Substitute for whole propositions"],"rules":[{"title":"Keep the auxiliary, omit repeated content","explanation":"Ellipsis removes words that the listener can recover from context. After a suitable auxiliary, a repeated verb phrase can be omitted. Match the auxiliary to the clause’s tense and structure.","pattern":"She can swim, and I **can too**.","commonMistakes":["I swim and she is too does not match the auxiliary to the lexical verb in the first clause."],"examples":["“I prepare the visitor guide every week.” Add that you do too: “**So do I**.”","“I restore the old portrait every week.” Add that you do too: “**So do I**.”"],"skill":"form"},{"title":"So and neither for shared experience","explanation":"Use **so + auxiliary + subject** to add agreement to a positive statement. Use **neither / nor + auxiliary + subject** after a negative one. This is an inverted agreement pattern, not ordinary statement order.","pattern":"I work here. **So do I.** / I don’t. **Neither do I.**","commonMistakes":["So I do is an emphatic acknowledgement, not the same pattern as So do I."],"examples":["“I do not prepare the visitor guide.” Add that you do not either: “**Neither do I**.”","“I do not restore the old portrait.” Add that you do not either: “**Neither do I**.”"],"skill":"meaning"},{"title":"One and ones replace count nouns","explanation":"One can replace a singular count noun and ones can replace plural count nouns when the noun is understood. They can combine with adjectives or determiners. They do not freely replace uncountable nouns.","pattern":"I prefer the blue **one**. / The old **ones** are cheaper.","commonMistakes":["Some advice → some, not some ones; advice is uncountable in this use."],"examples":["“She can prepare the visitor guide, and we **can** too.”","“She can restore the old portrait, and we **can** too.”"],"skill":"contrast"},{"title":"Substitute for whole propositions","explanation":"So can stand for an affirmative proposition after verbs such as think, hope and expect. Negative forms vary by verb: I hope not, I don’t think so. Such can point back to a type of thing already mentioned. Keep the reference unambiguous.","pattern":"Will it work? I **hope so**.","commonMistakes":["I don’t hope so is not the ordinary negative response; use I hope not."],"examples":["“Will they prepare the visitor guide on time?” Express a positive hope: “I hope **so**.”","“Will they restore the old portrait on time?” Express a positive hope: “I hope **so**.”"],"skill":"application"}],"tips":[],"source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-ellipsis"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"quizItems":[{"id":"aca88df8-a458-5324-abf7-959e6352eebd","topicSlug":"ellipsis-substitution","level":"C1","prompt":"“I prepare the visitor guide every week.” Add that you do too: “____.”","choices":[{"id":"A","text":"So am I"},{"id":"B","text":"So do I"},{"id":"C","text":"So I do"},{"id":"D","text":"Neither do I"}],"answerId":"B","hint":"The first clause is **positive present simple**.","explanation":"Positive present-simple agreement uses **so + do + I**.","keywords":["positive-agreement"],"skill":"positive-agreement","contextKey":"ellipsis-substitution-1","fingerprint":"77871020222581756f90a44c48a5a69338640ff9a1788f765aa66ac5643a5581","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-ellipsis"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["The first clause is **positive present simple**.","Positive present-simple agreement uses **so + do + I**.","Choose **So do I**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"Am does not match the ordinary lexical present-simple verb.","B":"Positive present-simple agreement uses **so + do + I**.","C":"So I do acknowledges or confirms a claim rather than adding another matching subject in the requested pattern.","D":"Neither adds agreement to a negative statement, but this one is positive."}}},{"id":"193ff333-5cf8-5274-a98c-09200a3a6fcf","topicSlug":"ellipsis-substitution","level":"C1","prompt":"“I do not prepare the visitor guide.” Add that you do not either: “____.”","choices":[{"id":"A","text":"Neither I do"},{"id":"B","text":"Neither am I"},{"id":"C","text":"Neither do I"},{"id":"D","text":"So do I"}],"answerId":"C","hint":"The first clause is **negative** and uses **do**.","explanation":"Negative agreement uses **neither + do + I**.","keywords":["negative-agreement"],"skill":"negative-agreement","contextKey":"ellipsis-substitution-1","fingerprint":"55579bc785617d4af4531f2e721e4f7d6f95d7682612654e529d97f7bb585f4b","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-ellipsis"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["The first clause is **negative** and uses **do**.","Negative agreement uses **neither + do + I**.","Choose **Neither do I**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"The agreement pattern inverts the auxiliary and subject.","B":"Am does not match the do auxiliary of the original statement.","C":"Negative agreement uses **neither + do + I**.","D":"So adds positive agreement, not agreement with this negative clause."}}},{"id":"41044944-ae7c-5496-af31-0bf38d2d4ef1","topicSlug":"ellipsis-substitution","level":"C1","prompt":"“She can prepare the visitor guide, and we ____ too.”","choices":[{"id":"A","text":"do"},{"id":"B","text":"have"},{"id":"C","text":"can"},{"id":"D","text":"are"}],"answerId":"C","hint":"Keep the modal **can** while leaving out the repeated action.","explanation":"Retain **can** and omit the recoverable action phrase.","keywords":["auxiliary-ellipsis"],"skill":"auxiliary-ellipsis","contextKey":"ellipsis-substitution-1","fingerprint":"668f89aff85ac22a91171942de0241aeb1a5fec7e0afa5eee0329a87594d8233","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-ellipsis"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["Keep the modal **can** while leaving out the repeated action.","Retain **can** and omit the recoverable action phrase.","Choose **can**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"Do would not preserve the stated modal ability meaning here.","B":"Have does not match the modal construction.","C":"Retain **can** and omit the recoverable action phrase.","D":"Are does not match the can construction."}}},{"id":"f8e5dc1f-e1f9-50de-ac62-aca08af3edb2","topicSlug":"ellipsis-substitution","level":"C1","prompt":"“Will they prepare the visitor guide on time?” Express a positive hope: “I hope ____.”","choices":[{"id":"A","text":"ones"},{"id":"B","text":"so"},{"id":"C","text":"not"},{"id":"D","text":"one"}],"answerId":"B","hint":"The missing content is a **whole positive statement**, so use so.","explanation":"**So** substitutes for the positive proposition that they will do it on time.","keywords":["proposition-substitution"],"skill":"proposition-substitution","contextKey":"ellipsis-substitution-1","fingerprint":"42f9bb7d6a2c41122c54f89a1c08271148cd880c6a3a846e724dc3036e4c9742","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-ellipsis"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["The missing content is a **whole positive statement**, so use so.","**So** substitutes for the positive proposition that they will do it on time.","Choose **so**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"Ones substitutes for plural count nouns, not a proposition.","B":"**So** substitutes for the positive proposition that they will do it on time.","C":"Not expresses a negative hope, opposite to the prompt.","D":"One substitutes for a count noun, not a whole proposition."}}},{"id":"4724e055-6f6f-5bf0-aaa7-ad30e561ce8d","topicSlug":"ellipsis-substitution","level":"C1","prompt":"“I restore the old portrait every week.” Add that you do too: “____.”","choices":[{"id":"A","text":"Neither do I"},{"id":"B","text":"So am I"},{"id":"C","text":"So do I"},{"id":"D","text":"So I do"}],"answerId":"C","hint":"The first clause is **positive present simple**.","explanation":"Positive present-simple agreement uses **so + do + I**.","keywords":["positive-agreement"],"skill":"positive-agreement","contextKey":"ellipsis-substitution-2","fingerprint":"982ad2e3f3a35e8c2704ca313aed676b79e443e80a0f29a0aee9cbb29f9132b4","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-ellipsis"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["The first clause is **positive present simple**.","Positive present-simple agreement uses **so + do + I**.","Choose **So do I**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"Neither adds agreement to a negative statement, but this one is positive.","B":"Am does not match the ordinary lexical present-simple verb.","C":"Positive present-simple agreement uses **so + do + I**.","D":"So I do acknowledges or confirms a claim rather than adding another matching subject in the requested pattern."}}},{"id":"55539fb9-fc77-5d68-a431-8adfdb21e36e","topicSlug":"ellipsis-substitution","level":"C1","prompt":"“I do not restore the old portrait.” Add that you do not either: “____.”","choices":[{"id":"A","text":"Neither am I"},{"id":"B","text":"Neither do I"},{"id":"C","text":"So do I"},{"id":"D","text":"Neither I do"}],"answerId":"B","hint":"The first clause is **negative** and uses **do**.","explanation":"Negative agreement uses **neither + do + I**.","keywords":["negative-agreement"],"skill":"negative-agreement","contextKey":"ellipsis-substitution-2","fingerprint":"c76e9d5bbb22338bb373b5ea53a842a30384f86fa895694495ed5ad16d2b0b2e","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-ellipsis"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["The first clause is **negative** and uses **do**.","Negative agreement uses **neither + do + I**.","Choose **Neither do I**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"Am does not match the do auxiliary of the original statement.","B":"Negative agreement uses **neither + do + I**.","C":"So adds positive agreement, not agreement with this negative clause.","D":"The agreement pattern inverts the auxiliary and subject."}}},{"id":"8d4bdd30-9aa5-5343-ad6f-fc4b9831a662","topicSlug":"ellipsis-substitution","level":"C1","prompt":"“She can restore the old portrait, and we ____ too.”","choices":[{"id":"A","text":"have"},{"id":"B","text":"can"},{"id":"C","text":"are"},{"id":"D","text":"do"}],"answerId":"B","hint":"Keep the modal **can** while leaving out the repeated action.","explanation":"Retain **can** and omit the recoverable action phrase.","keywords":["auxiliary-ellipsis"],"skill":"auxiliary-ellipsis","contextKey":"ellipsis-substitution-2","fingerprint":"a7b07a3cc074352b776c80819f57417ca15e075af926ecda369afa45961b066e","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-ellipsis"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["Keep the modal **can** while leaving out the repeated action.","Retain **can** and omit the recoverable action phrase.","Choose **can**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"Have does not match the modal construction.","B":"Retain **can** and omit the recoverable action phrase.","C":"Are does not match the can construction.","D":"Do would not preserve the stated modal ability meaning here."}}},{"id":"065f9cda-5c28-5e73-ae04-b93c0732726d","topicSlug":"ellipsis-substitution","level":"C1","prompt":"“Will they restore the old portrait on time?” Express a positive hope: “I hope ____.”","choices":[{"id":"A","text":"one"},{"id":"B","text":"ones"},{"id":"C","text":"so"},{"id":"D","text":"not"}],"answerId":"C","hint":"The missing content is a **whole positive statement**, so use so.","explanation":"**So** substitutes for the positive proposition that they will do it on time.","keywords":["proposition-substitution"],"skill":"proposition-substitution","contextKey":"ellipsis-substitution-2","fingerprint":"4ae3b3f8521b91178dc10751be3f7060d6dbad3bbbe995828ef8f2d49f519051","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-ellipsis"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["The missing content is a **whole positive statement**, so use so.","**So** substitutes for the positive proposition that they will do it on time.","Choose **so**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"One substitutes for a count noun, not a whole proposition.","B":"Ones substitutes for plural count nouns, not a proposition.","C":"**So** substitutes for the positive proposition that they will do it on time.","D":"Not expresses a negative hope, opposite to the prompt."}}},{"id":"fd59a672-c5c9-57d2-a4ae-8d54fc8a5ad3","topicSlug":"ellipsis-substitution","level":"C1","prompt":"“I measure the garden fence every week.” Add that you do too: “____.”","choices":[{"id":"A","text":"Neither do I"},{"id":"B","text":"So am I"},{"id":"C","text":"So do I"},{"id":"D","text":"So I do"}],"answerId":"C","hint":"The first clause is **positive present simple**.","explanation":"Positive present-simple agreement uses **so + do + I**.","keywords":["positive-agreement"],"skill":"positive-agreement","contextKey":"ellipsis-substitution-3","fingerprint":"6a6f32a77c17f6054a25f6441f27d8f97427d71f6f125a07e0786503796a316a","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-ellipsis"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["The first clause is **positive present simple**.","Positive present-simple agreement uses **so + do + I**.","Choose **So do I**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"Neither adds agreement to a negative statement, but this one is positive.","B":"Am does not match the ordinary lexical present-simple verb.","C":"Positive present-simple agreement uses **so + do + I**.","D":"So I do acknowledges or confirms a claim rather than adding another matching subject in the requested pattern."}}},{"id":"e42da226-083b-510c-a5ef-9a1514a8e2cd","topicSlug":"ellipsis-substitution","level":"C1","prompt":"“I do not measure the garden fence.” Add that you do not either: “____.”","choices":[{"id":"A","text":"Neither do I"},{"id":"B","text":"So do I"},{"id":"C","text":"Neither I do"},{"id":"D","text":"Neither am I"}],"answerId":"A","hint":"The first clause is **negative** and uses **do**.","explanation":"Negative agreement uses **neither + do + I**.","keywords":["negative-agreement"],"skill":"negative-agreement","contextKey":"ellipsis-substitution-3","fingerprint":"934d513ed2f2949d40167f833dee4c8ad76a190b7da9185f9fa8cf8738d14aca","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-ellipsis"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["The first clause is **negative** and uses **do**.","Negative agreement uses **neither + do + I**.","Choose **Neither do I**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"Negative agreement uses **neither + do + I**.","B":"So adds positive agreement, not agreement with this negative clause.","C":"The agreement pattern inverts the auxiliary and subject.","D":"Am does not match the do auxiliary of the original statement."}}},{"id":"856948b7-50f7-5580-a603-d9e0d4e28921","topicSlug":"ellipsis-substitution","level":"C1","prompt":"“She can measure the garden fence, and we ____ too.”","choices":[{"id":"A","text":"have"},{"id":"B","text":"can"},{"id":"C","text":"are"},{"id":"D","text":"do"}],"answerId":"B","hint":"Keep the modal **can** while leaving out the repeated action.","explanation":"Retain **can** and omit the recoverable action phrase.","keywords":["auxiliary-ellipsis"],"skill":"auxiliary-ellipsis","contextKey":"ellipsis-substitution-3","fingerprint":"83add014e254949a407e2a2239dca75b639822b8f16853931d95ea7a679df9dd","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-ellipsis"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["Keep the modal **can** while leaving out the repeated action.","Retain **can** and omit the recoverable action phrase.","Choose **can**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"Have does not match the modal construction.","B":"Retain **can** and omit the recoverable action phrase.","C":"Are does not match the can construction.","D":"Do would not preserve the stated modal ability meaning here."}}},{"id":"6c7b072b-195b-55ff-ab45-394cc6dc371f","topicSlug":"ellipsis-substitution","level":"C1","prompt":"“Will they measure the garden fence on time?” Express a positive hope: “I hope ____.”","choices":[{"id":"A","text":"ones"},{"id":"B","text":"so"},{"id":"C","text":"not"},{"id":"D","text":"one"}],"answerId":"B","hint":"The missing content is a **whole positive statement**, so use so.","explanation":"**So** substitutes for the positive proposition that they will do it on time.","keywords":["proposition-substitution"],"skill":"proposition-substitution","contextKey":"ellipsis-substitution-3","fingerprint":"2b50959eb51fe44f17c1ffa3ab727dc273b9d2c0b109113dbd1fc5be0a93edf1","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-ellipsis"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["The missing content is a **whole positive statement**, so use so.","**So** substitutes for the positive proposition that they will do it on time.","Choose **so**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"Ones substitutes for plural count nouns, not a proposition.","B":"**So** substitutes for the positive proposition that they will do it on time.","C":"Not expresses a negative hope, opposite to the prompt.","D":"One substitutes for a count noun, not a whole proposition."}}},{"id":"16cf647e-ac63-594d-aded-71273511d714","topicSlug":"ellipsis-substitution","level":"C1","prompt":"“I translate the travel leaflet every week.” Add that you do too: “____.”","choices":[{"id":"A","text":"Neither do I"},{"id":"B","text":"So am I"},{"id":